css:
.all {
  font-family: 'Times New Roman', Times, serif;
  font-size: 12px;
  padding: 10px;
  width: 100%;
}

/* ── Company header ──────────────────────────────────────────────────────── */
.company-logo {
  float: left;
  max-height: 55px;
  margin-top: 10px;
  margin-right: 12px;
}

.comp {
  float: left;
  margin-left: 10px;
}

.comp h4 {
  margin: 0 0 4px 0;
  font-size: 16px;
}

.comp p {
  margin: 1px 0;
}

/* ── Title bar ───────────────────────────────────────────────────────────── */
.order {
  background-color: #f4f7f7;
  border-bottom: 2px solid #333;
  border-radius: 6px;
  text-align: center;
  font-weight: bold;
  font-size: 25px;
  padding: 6px;
  margin: 8px 0;
}

/* ── Two-column layout ───────────────────────────────────────────────────── */
.flex {
  display: flex;
  justify-content: space-between;
}

.box {
  border-radius: 6px;
  border: 1px solid #ccc;
  background-color: #f4f7f7;
  padding: 6px 8px;
  width: 48%;
  margin-bottom: 6px;
  line-height: 1.6;
}

/* ── Items table ─────────────────────────────────────────────────────────── */
.thead-row {
  background-color: #89CFF0;
  font-size: 9px;
  border-bottom: 2px solid #333;
  text-transform: uppercase;
}

.thead-row th {
  padding: 5px;
  text-align: left;
}

.item-row td {
  padding: 4px 5px;
  font-size: 10px;
  border-bottom: 0.8px solid #ccc;
}

.batch-info {
  font-size: 9px;
  color: #555;
}

/* ── Totals ──────────────────────────────────────────────────────────────── */
.deductions {
  float: right;
  text-align: left;
  margin-top: 8px;
  border-collapse: collapse;
}

.deductions td {
  padding: 4px 10px;
  border-bottom: 0.8px solid #ccc;
}

.grand-total-row td {
  background-color: #89CFF0;
  font-size: 12px;
}

/* ── Footer blocks ───────────────────────────────────────────────────────── */
.in-words {
  margin-top: 10px;
  padding: 6px;
  background-color: #f9f9f9;
  border-left: 3px solid #7ac143;
}

.footer-note {
  margin-top: 8px;
  font-size: 10px;
  color: #555;
  text-align: center;
}

.sig-col {
  width: 30%;
  font-size: 15px;
}

/* ════════════════════════════════════════════════════════════════════════════
   EFRIS / URA KAKASA section
   Appears only when the invoice has been submitted to URA EFRIS (T109).
   Mirrors the SAP B1 EFRIS invoice footer strip.
   ════════════════════════════════════════════════════════════════════════════ */

.efris-section {
  margin-top: 18px;
  border: 1.5px solid #444;
  border-radius: 5px;
  overflow: hidden;
  page-break-inside: avoid;  /* keep the EFRIS block on one page */
}

/* ── "KAKASA with EFRIS" header bar ─────────────────────────────────────── */
.efris-header {
  text-align: center;
  font-weight: bold;
  font-size: 12px;
  letter-spacing: 2px;
  padding: 4px 8px;
  border-bottom: 1px solid #444;
  background-color: #ffffff;
}

/* ── Three-column body: logo | details | QR ─────────────────────────────── */
.efris-body {
  display: flex;
  align-items: center;
  padding: 8px 14px;
  gap: 14px;
}

/* URA logo column */
.efris-logo-wrap {
  min-width: 62px;
  text-align: center;
  flex-shrink: 0;
}

.ura-logo {
  float: none !important;  /* override global img{float:left} */
  max-height: 58px;
  margin: 0 !important;
  display: block;
}

/* EFRIS fields column */
.efris-details {
  flex: 1;
  font-size: 11px;
  line-height: 1.8;
}

.efris-row {
  display: flex;
  gap: 6px;
}

.efris-lbl {
  font-weight: bold;
  white-space: nowrap;
  min-width: 130px;
}

.efris-val {
  font-size: 11px;
  word-break: break-all;
}

/* QR code column */
.efris-qr-wrap {
  min-width: 94px;
  text-align: center;
  flex-shrink: 0;
}

.efris-qr-img {
  float: none !important;  /* override global img{float:left} */
  width: 90px;
  height: 90px;
  margin: 0 !important;
  display: block;
  border: 1px solid #ddd;
}

/* ── Bottom customer message ─────────────────────────────────────────────── */
.efris-msg {
  border-top: 1px solid #ccc;
  padding: 4px 14px;
  font-size: 10px;
  color: #333;
  text-align: center;
  background-color: #fafafa;
}
